import Mathlib
import Aesop

set_option maxHeartbeats 0

open BigOperators Real Nat Topology Rat

theorem algebra_2928
  (a b c : ℂ)
  (h : ∀ z : ℂ, z.im ≠ 0 → (∃ r : ℝ, a * z ^ 2 + b * z + c = r)) :
  a = 0 ∧ b = 0 ∧ ∃ r : ℝ, c = r := by
  have h₁ : a.re = 0 := by
    by_contra h₁
    have h₂ : a.re ≠ 0 := h₁
    -- Evaluate at z = i, z = -i, z = 1 + i, z = 1 - i, z = 2i, z = -2i, z = (1 + 2i)
    have h₃ := h (Complex.I)
    have h₄ := h (-Complex.I)
    have h₅ := h (Complex.I + 1)
    have h₆ := h (Complex.I + 2)
    have h₇ := h (Complex.I + 3)
    have h₈ := h (-Complex.I + 1)
    have h₉ := h (-Complex.I + 2)
    have h₁₀ := h (-Complex.I + 3)
    have h₁₁ := h (2 * Complex.I)
    have h₁₂ := h (-2 * Complex.I)
    have h₁₃ := h (Complex.I + 4)
    have h₁₄ := h (-Complex.I + 4)
    -- Normalize the expressions to get equations
    norm_num [Complex.ext_iff, pow_two, Complex.ext_iff, pow_two, Complex.I_mul_I,
      Complex.I_mul_I, Complex.I_mul_I, Complex.I_mul_I, Complex.I_mul_I, Complex.I_mul_I] at h₃ h₄ h₅ h₆ h₇ h₈ h₉ h₁₀ h₁₁ h₁₂ h₁₃ h₁₄
    -- Simplify the equations to find a contradiction
    <;>
    (try
      norm_num at * <;>
      (try
        (try
          ring_nf at * <;>
          norm_num at * <;>
          (try
            linarith)))) <;>
